dataTransform.transform:
(
  $tz := $state.claims.metadata.settings.TimeZone != null ? $state.claims.metadata.settings.TimeZone : $momentTzGuess(true);
  edges.node.(
    $pickedAt := $last(inventoryPickSteps.edges.node.pickedAt[$ != null]);
    {
      "id": id,
      "serialNumber": serialNumber,
      "quantity": quantity,
      "pickedAt": $pickedAt ? (
        $tz ?
          $moment($pickedAt).tz($tz).format("M/D/YYYY h:mma z") :
          $moment($pickedAt).utc().format("M/D/YYYY h:mma") & " UTC"
      )
    }
  )
)

(
  $tz := $state.claims.metadata.settings.TimeZone != null ? $state.claims.metadata.settings.TimeZone : $momentTzGuess(true);

  [edges.node.(
    $packedAt := $last(inventories.edges.node.inventoryPickSteps.edges.node.packedAt[$ != null]);
    {
      "id": id,
      "orderLineRelease": orderLineRelease,
      "product": orderLineRelease.orderLine.product.code & " - " & orderLineRelease.orderLine.product.description,
      "quantityDisplay": quantity.value & " " & quantity.unitId,
      "packedQuantityDisplay": packedQuantity != null ? packedQuantity.value & " " & packedQuantity.unitId : "0 " & quantity.unitId,
      "quantity": quantity,
      "packedQuantity": packedQuantity,
      "packedAt": $packedAt ? (
        $tz ?
          $moment($packedAt).tz($tz).format("M/D/YYYY h:mma z") :
          $moment($packedAt).utc().format("M/D/YYYY h:mma") & " UTC"
      ),
      "background": packedQuantity = quantity ? "custom" : "paper",
      "customBackground": "#9fd678" 
    }
  )]
)
